const COLORREF BG=RGB(10,12,21),SIDEBAR=RGB(15,16,28),PANEL=RGB(24,23,36),PANEL2=RGB(34,31,44),BORDER=RGB(69,50,59),TEXT=RGB(245,232,214),MUTED=RGB(179,154,146),GREEN=RGB(93,223,195),RED=RGB(255,104,86),AMBER=RGB(255,188,93),BLUE=RGB(159,169,255);
