void drawText(HDC dc,int x,int y,int w,int h,const std::wstring& s,COLORREF color=TEXT,int size=10,bool bold=false,UINT flags=DT_LEFT|DT_VCENTER|DT_SINGLELINE){SetBkMode(dc,TRANSPARENT);SetTextColor(dc,color);HFONT f=CreateFontW(-size,0,0,0,bold?FW_BOLD:FW_NORMAL,FALSE,FALSE,FALSE,DEFAULT_CHARSET,OUT_DEFAULT_PRECIS,CLIP_DEFAULT_PRECIS,CLEARTYPE_QUALITY,DEFAULT_PITCH|FF_DONTCARE,L"Segoe UI");auto old=SelectObject(dc,f);RECT r{x,y,x+w,y+h};DrawTextW(dc,s.c_str(),static_cast<int>(s.size()),&r,flags);SelectObject(dc,old);DeleteObject(f);}
void panel(HDC dc,RECT r,COLORREF color=PANEL,int radius=10){HBRUSH b=CreateSolidBrush(color);HPEN p=CreatePen(PS_SOLID,1,BORDER);auto ob=SelectObject(dc,b);auto op=SelectObject(dc,p);RoundRect(dc,r.left,r.top,r.right,r.bottom,radius,radius);SelectObject(dc,ob);SelectObject(dc,op);DeleteObject(b);DeleteObject(p);}
std::wstring xmlDecode(std::wstring s){const std::pair<const wchar_t*,const wchar_t*> reps[]={{L"&amp;",L"&"},{L"&lt;",L"<"},{L"&gt;",L">"},{L"&quot;",L"\""},{L"&apos;",L"'"}};for(auto [a,b]:reps){size_t p=0;while((p=s.find(a,p))!=std::wstring::npos){s.replace(p,wcslen(a),b);p+=wcslen(b);}}return s;}
std::wstring eventData(const std::wstring& xml,const std::wstring& name){std::wstring key=L"Name=\""+name+L"\"";size_t p=xml.find(key);if(p==std::wstring::npos)return L"";p=xml.find(L">",p);if(p==std::wstring::npos)return L"";size_t q=xml.find(L"</Data>",p+1);if(q==std::wstring::npos)return L"";return xmlDecode(xml.substr(p+1,q-p-1));}
std::wstring eventTime(const std::wstring& xml){size_t p=xml.find(L"<TimeCreated");if(p==std::wstring::npos)return L"";p=xml.find(L"SystemTime=\"",p);if(p==std::wstring::npos)return L"";p+=12;size_t q=xml.find(L"\"",p);if(q==std::wstring::npos)return L"";return xml.substr(p,q-p);}
bool parseFileTime(const std::wstring& iso,FILETIME& out){SYSTEMTIME st{};int y=0,mo=0,d=0,h=0,mi=0,se=0;if(swscanf(iso.c_str(),L"%d-%d-%dT%d:%d:%d",&y,&mo,&d,&h,&mi,&se)!=6)return false;st.wYear=static_cast<WORD>(y);st.wMonth=static_cast<WORD>(mo);st.wDay=static_cast<WORD>(d);st.wHour=static_cast<WORD>(h);st.wMinute=static_cast<WORD>(mi);st.wSecond=static_cast<WORD>(se);return SystemTimeToFileTime(&st,&out)!=0;}
std::wstring prettyTime(const std::wstring& s){if(s.size()>=19)return s.substr(0,19).replace(10,1,L" ");return s;}
std::wstring windowsError(DWORD code){LPWSTR buffer=nullptr;DWORD n=FormatMessageW(FORMAT_MESSAGE_ALLOCATE_BUFFER|FORMAT_MESSAGE_FROM_SYSTEM|FORMAT_MESSAGE_IGNORE_INSERTS,nullptr,code,0,reinterpret_cast<LPWSTR>(&buffer),0,nullptr);std::wstring m=n&&buffer?std::wstring(buffer,n):L"Windows error "+std::to_wstring(code);if(buffer)LocalFree(buffer);return m;}
bool readSecurityEvents(std::vector<FailedEvent>& out,std::wstring& error){EVT_HANDLE q=EvtQuery(nullptr,L"Security",L"*[System[(EventID=4625)]]",EvtQueryChannelPath|EvtQueryReverseDirection);if(!q){error=windowsError(GetLastError());return false;}EVT_HANDLE batch[64]{};DWORD returned=0;bool ok=true;while(out.size()<250&&EvtNext(q,64,batch,1000,0,&returned)){for(DWORD i=0;i<returned&&out.size()<250;++i){DWORD bytes=0,props=0;EvtRender(nullptr,batch[i],EvtRenderEventXml,0,nullptr,&bytes,&props);DWORD err=GetLastError();if(err!=ERROR_INSUFFICIENT_BUFFER||bytes==0){EvtClose(batch[i]);continue;}std::vector<wchar_t> buffer((bytes/sizeof(wchar_t))+1);if(!EvtRender(nullptr,batch[i],EvtRenderEventXml,bytes,buffer.data(),&bytes,&props)){EvtClose(batch[i]);continue;}std::wstring xml(buffer.data());FailedEvent e;e.time=eventTime(xml);e.account=eventData(xml,L"TargetUserName");e.ip=eventData(xml,L"IpAddress");e.workstation=eventData(xml,L"WorkstationName");e.logonType=eventData(xml,L"LogonType");e.status=eventData(xml,L"Status");e.subStatus=eventData(xml,L"SubStatus");parseFileTime(e.time,e.ft);out.push_back(std::move(e));EvtClose(batch[i]);}if(returned==0)break;}DWORD finalError=GetLastError();if(finalError!=ERROR_NO_MORE_ITEMS&&out.empty()){error=windowsError(finalError);ok=false;}EvtClose(q);return ok;}
void makeDemo(){events.clear();SYSTEMTIME now{};GetSystemTime(&now);FILETIME ft{};SystemTimeToFileTime(&now,&ft);for(int i=0;i<12;++i){FailedEvent e;e.account=L"sample-user";e.ip=L"203.0.113.24";e.workstation=L"DEMO-PC";e.logonType=L"3";e.status=L"0xC000006D";e.subStatus=L"0xC000006A";e.ft=ft;e.time=L"DEMO · recent";events.push_back(std::move(e));}statusText=L"DEMO MODE · synthetic events only";lastError.clear();}
void refresh(){if(demoMode){makeDemo();InvalidateRect(window,nullptr,TRUE);return;}std::vector<FailedEvent> next;std::wstring error;if(readSecurityEvents(next,error)){events=std::move(next);statusText=L"Security log read · "+std::to_wstring(events.size())+L" recent failed-logon events · checked "+[](){SYSTEMTIME s{};GetLocalTime(&s);wchar_t b[40]{};swprintf(b,40,L"%02u:%02u:%02u",s.wHour,s.wMinute,s.wSecond);return std::wstring(b);}();lastError.clear();}else{statusText=L"Could not read the Security log. No Windows settings were changed.";lastError=error;}InvalidateRect(window,nullptr,TRUE);}
int recentCount(const std::wstring& key,bool byIp){FILETIME nowFt{};GetSystemTimeAsFileTime(&nowFt);ULARGE_INTEGER now{};now.LowPart=nowFt.dwLowDateTime;now.HighPart=nowFt.dwHighDateTime;int n=0;for(const auto&e:events){const std::wstring& v=byIp?e.ip:e.account;if(v!=key)continue;ULARGE_INTEGER t{};t.LowPart=e.ft.dwLowDateTime;t.HighPart=e.ft.dwHighDateTime;if(t.QuadPart<=now.QuadPart&&now.QuadPart-t.QuadPart<=300ULL*10000000ULL)++n;}return n;}
std::wstring alertSummary(){std::map<std::wstring,int> ips,users;for(const auto&e:events){if(!e.ip.empty()&&e.ip!=L"-"&&e.ip!=L"127.0.0.1"&&e.ip!=L"::1")++ips[e.ip];if(!e.account.empty()&&e.account!=L"-")++users[e.account];}std::wstring result;for(const auto&[v,n]:ips)if(recentCount(v,true)>=10){if(!result.empty())result+=L"   ";result+=L"SOURCE "+v+L" · "+std::to_wstring(recentCount(v,true))+L" / 5 min";}for(const auto&[v,n]:users)if(recentCount(v,false)>=10){if(!result.empty())result+=L"   ";result+=L"ACCOUNT "+v+L" · "+std::to_wstring(recentCount(v,false))+L" / 5 min";}return result;}
void roundedButton(HDC dc,RECT r,const std::wstring& label,bool primary,int action){panel(dc,r,primary?GREEN:PANEL2,7);drawText(dc,r.left,r.top,r.right-r.left,r.bottom-r.top,label,primary?BG:TEXT,9,true,DT_CENTER|DT_VCENTER|DT_SINGLELINE);hits.push_back({r,action});}
