 int x=250,w=W-x-28;drawText(dc,x,22,w,16,L"LOGINSHIELD NG  /  WINDOWS SECURITY",MUTED,8,true);drawText(dc,x,45,w,34,L"Failed sign-in monitor",TEXT,23,true);roundedButton(dc,{W-270,36,W-170,70},L"Refresh",false,1);roundedButton(dc,{W-158,36,W-28,70},demoMode?L"Read live log":L"Demo sample",false,2);
 int gap=12,cw=(w-2*gap)/3;panel(dc,{x,99,x+cw,184},PANEL);drawText(dc,x+14,109,cw-28,15,L"EVENTS LOADED",MUTED,8,true);drawText(dc,x+14,132,cw-28,31,std::to_wstring(events.size()),TEXT,22,true);drawText(dc,x+14,164,cw-28,13,L"Security Event ID 4625",GREEN,8);
 std::wstring alert=alertSummary();panel(dc,{x+cw+gap,99,x+2*cw+gap,184},alert.empty()?PANEL:PANEL2);drawText(dc,x+cw+gap+14,109,cw-28,15,L"REVIEW SIGNAL",MUTED,8,true);drawText(dc,x+cw+gap+14,132,cw-28,37,alert.empty()?L"No threshold alerts":L"Repeated attempts",alert.empty()?GREEN:AMBER,12,true,DT_LEFT|DT_VCENTER|DT_WORDBREAK);drawText(dc,x+cw+gap+14,164,cw-28,13,L"10+ events per account/source in 5 min",MUTED,8);
 panel(dc,{x+2*(cw+gap),99,W-28,184},PANEL);drawText(dc,x+2*(cw+gap)+14,109,cw-28,15,L"REFRESH",MUTED,8,true);drawText(dc,x+2*(cw+gap)+14,132,cw-28,35,L"Every 15 seconds",TEXT,13,true);drawText(dc,x+2*(cw+gap)+14,164,cw-28,13,L"Events remain in memory only",GREEN,8);
 panel(dc,{x,198,W-28,H-252},PANEL);drawText(dc,x+15,209,w-30,20,L"RECENT FAILED LOGONS",TEXT,11,true);int ty=237;drawText(dc,x+18,ty,150,17,L"TIME (UTC)",MUTED,8,true);drawText(dc,x+178,ty,165,17,L"ACCOUNT",MUTED,8,true);drawText(dc,x+350,ty,130,17,L"SOURCE IP",MUTED,8,true);drawText(dc,x+488,ty,130,17,L"WORKSTATION",MUTED,8,true);drawText(dc,x+625,ty,76,17,L"TYPE",MUTED,8,true);drawText(dc,x+715,ty,145,17,L"STATUS / SUBSTATUS",MUTED,8,true);int shown=0;for(const auto&e:events){if(shown>=std::max(1,(H-320)/29))break;int y=ty+22+shown*29;RECT row{x+12,y,W-40,y+27};if(shown%2==0){HBRUSH rb=CreateSolidBrush(PANEL2);FillRect(dc,&row,rb);DeleteObject(rb);}drawText(dc,x+18,y,150,27,prettyTime(e.time),MUTED,8);drawText(dc,x+178,y,165,27,e.account.empty()?L"(unknown)":e.account,TEXT,8,true);drawText(dc,x+350,y,130,27,e.ip.empty()?L"—":e.ip,RGB(201,212,223),8);drawText(dc,x+488,y,130,27,e.workstation.empty()?L"—":e.workstation,MUTED,8);drawText(dc,x+625,y,76,27,e.logonType.empty()?L"—":e.logonType,MUTED,8);drawText(dc,x+715,y,145,27,e.status+L" / "+e.subStatus,RED,8);++shown;}if(events.empty())drawText(dc,x+20,ty+50,w-40,34,demoMode?L"No sample events.":L"No recent events, or Security log access is unavailable.",MUTED,9);
 RECT bar{x,H-43,W-28,H-27};panel(dc,bar,PANEL2,5);drawText(dc,x+10,H-43,w-20,16,statusText,lastError.empty()?MUTED:AMBER,8);drawText(dc,x,H-22,w,14,L"Passive review only · never blocks accounts, changes firewall rules, or uploads logs.",MUTED,8);
